#!/usr/bin/env python3
from __future__ import annotations
import pathlib, sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
def text(p): return (ROOT/p).read_text()
checks=[]
def check(n,c): checks.append((n,bool(c)))

cargo=text('Cargo.toml'); core=text('crates/sparkbridge-core/src/lib.rs'); protocol=text('crates/sparkbridge-protocol/src/lib.rs')
cache=text('crates/sparkbridge-cache/src/lib.rs'); validation=text('crates/sparkbridge-validation/src/lib.rs')
execution=text('crates/sparkbridge-execution/src/lib.rs'); server=text('apps/sparkbridge-server/src/main.rs')
store=text('apps/sparkbridge-server/src/store.rs'); runtime=text('apps/sparkbridge-server/src/agent_runtime.rs')
executor=text('apps/sparkbridge-executor/src/main.rs'); task=text('crates/sparkbridge-task/src/lib.rs')
cli=text('apps/sparkbridge-cli/src/main.rs'); config=text('crates/sparkbridge-config/src/lib.rs')
readme=text('README.md'); security=text('SECURITY.md'); user=text('docs/USER_MANUAL.md'); install=text('docs/INSTALLATION_GUIDE.md')

check('workspace version is 0.12.0','version = "0.12.0"' in cargo)
check('protocol is 1.10','PROTOCOL_MINOR: u16 = 10' in protocol)
check('schema is v9','SCHEMA_VERSION: u32 = 9' in store and 'PRAGMA user_version = 9' in store)
check('cache and validation crates are workspace members','crates/sparkbridge-cache' in cargo and 'crates/sparkbridge-validation' in cargo)
check('iteration 10 features negotiate','ITERATION_10_CACHE_VALIDATION' in core and all(x in core for x in ['ActionCache','ToolchainFingerprints','MultiPlatformValidation','BuildAffinity']))
check('server advertises iteration 10','ITERATION_10_CACHE_VALIDATION' in server)
check('cache trust has strong best-effort disabled',all(x in protocol for x in ['pub enum CacheTrust','Strong','BestEffort','Disabled']))
check('actions can target platform and architecture','required_platform' in protocol and 'required_architecture' in protocol)
check('action records expose cache provenance',all(x in protocol for x in ['cache_key','toolchain_digest','cache_hit','cache_source_action_id']))
check('cached actions require immutable candidates','cached actions require an immutable candidate input' in cache)
check('only pure actions may be cached','only pure actions may be cached' in cache)
check('secret dependent actions are not cached','cached actions do not permit secret-dependent inputs' in cache)
check('strong cache requires network none','strong cache requires network=none' in cache)
check('strong cache scheduling requires hermetic domain capability','cache:strong' in server and 'CacheTrust::Strong' in server)
check('native host domain does not overclaim strong cache','cache:strong' not in execution)
check('strong cache requires toolchain fingerprint','strong cache requires a valid toolchain fingerprint' in cache)
check('strong cache rejects unknown required tool versions','strong cache refuses unknown tool version' in cache)
check('cache key includes candidate','candidate_id: &' in cache)
check('cache key includes platform and architecture','required_platform' in cache and 'required_architecture' in cache)
check('cache key includes argv cwd environment','argv:' in cache and 'relative_cwd:' in cache and 'env:' in cache)
check('cache key includes timeout and output bounds','timeout_ms:' in cache and 'max_output_bytes:' in cache)
check('cache key includes network intent','network_policy:' in cache and 'declared_hosts:' in cache)
check('cache key includes required capabilities','required_capabilities:' in cache)
check('cache key includes toolchain digest','toolchain_digest:' in cache)
check('toolchain fingerprint contains platform architecture domain executor',all(x in protocol for x in ['pub platform: String','pub architecture: String','pub domain: String','pub executor_version: String']))
check('toolchain fingerprint records command versions','command_versions' in protocol and 'command_versions.insert' in execution)
check('toolchain fingerprint records selected environment','SDKROOT' in execution and 'DEVELOPER_DIR' in execution and 'RUSTUP_TOOLCHAIN' in execution)
check('toolchain fingerprint digest is content addressed','fingerprint_digest' in cache and 'fingerprint.digest' in execution)
check('execution domains report toolchain fingerprint','toolchain: Some(toolchain)' in execution)
check('action cache is durable sqlite','CREATE TABLE IF NOT EXISTS action_cache' in store and 'get_action_cache' in store and 'put_action_cache' in store)
check('cache has bounded LRU-style pruning','prune_action_cache' in store and 'ORDER BY last_used_unix_ms ASC' in store and 'action_cache_max_entries' in config)
check('successful cacheable results are stored in CAS','ActionCacheRecord' in server and 'state.cas.put_bytes' in server and 'result_digest' in server)
check('cached CAS object self-binds cache key and toolchain','CachedActionResultObject' in cache and 'cached action result cache-key mismatch' in cache and 'cached action result toolchain mismatch' in cache and 'encode_cached_result' in server and 'decode_cached_result' in server)
check('strong cache reuse reloads immutable CAS result','load_cached_result' in server and 'state.cas.get_bytes' in server and 'verifying cached action result' in server)
check('strong hit alone can skip execution','request.spec.cache_trust == CacheTrust::Strong' in server and 'cached_result' in server)
check('best effort hit does not become authoritative skip','request.spec.cache_trust == CacheTrust::Strong' in server and 'cache_source_action_id' in server)
check('scheduler uses cache affinity','Build affinity' in server and 'selected_cache' in server)
check('scheduler matches target platform and architecture','matching_domain' in server and 'required_platform' in server and 'required_architecture' in server)
check('validation protocol has matrices and targets',all(x in protocol for x in ['ValidationMatrixCreateRequest','ValidationTargetSpec','ValidationRunRecord','ValidationTargetRecord']))
check('validation targets carry platform architecture cache trust',all(x in protocol for x in ['pub platform: String','pub architecture: Option<String>','pub cache_trust: CacheTrust']))
check('validation run status requires aggregate target state','derive_run_status' in validation and 'all(|t| t.status == ActionStatus::Succeeded)' in validation)
check('validation runs persist durably','CREATE TABLE IF NOT EXISTS validation_runs' in store and 'save_validation_run' in store and 'list_validation_runs' in store)
check('validation admin routes exist','/api/v1/admin/validations' in server and 'admin_create_validation' in server)
check('validation matrix target count is bounded','validation_max_targets' in config and 'request.targets.len() > state.config.validation_max_targets' in server)
check('validation scheduling binds candidate workspace','candidate workspace does not match validation workspace' in server)
check('validation creation schedules candidate-bound actions','candidate_id: Some(request.candidate_id.clone())' in server)
check('cross-node candidate validation requires same workspace','candidate validation requires this executor to advertise the same logical workspace' in server)
check('promotion remains owner pinned','candidate.node_id != id || candidate.workspace_id != request.workspace_id' in server)
check('task spec supports fanout','validation_fanout' in task)
check('task projection supports multiple pending actions','pending_action_ids' in task)
check('agent runtime schedules validation fanout','schedule_validation_fanout' in runtime and 'fanout' in runtime)
check('agent waits for all fanout actions','pending_action_ids' in runtime and 'actions.iter().any(|action| !matches!' in runtime and 'all_succeeded=actions.iter().all' in runtime)
check('agent validation produces durable validation run evidence','validation_action_ids' in task and 'persist_task_validation_run' in runtime and 'save_validation_run' in runtime and 'task:{}:candidate:{}' in runtime)
check('fanout failure returns to repair cycle','repair_cycles' in runtime and 'validation fan-out' in runtime)
check('agent validation actions carry target platform','required_platform: template.platform.clone()' in runtime)
check('agent validation actions carry cache trust','cache_trust: template.cache_trust' in runtime)
check('workspace policy can require validation platforms','required_validation_platforms' in protocol)
check('live promotion enforces required platforms','promotion requires successful validation on' in server and 'ValidationRunStatus::Succeeded' in server)
check('dry-run promotion does not require validation matrix','if !request.dry_run && !policy.required_validation_platforms.is_empty()' in server)
check('CLI exposes cache workflow','Command::Cache' in cli and 'CacheCommand' in cli)
check('CLI exposes validation workflow','Command::Validations' in cli and 'ValidationsCommand' in cli)
check('CLI action creation supports cache and target platform','CacheTrustArg' in cli and 'platform' in cli and 'architecture' in cli)
check('example validation matrix exists',(ROOT/'config/validation.example.json').exists())
check('workspace policy example requires platform matrix','required_validation_platforms' in text('config/workspace-policy.example.json'))
check('manuals retain cache and validation guidance','v0.12.0' in user and '1.10' in user and 'validation' in user.lower() and 'v0.12.0' in install)
check('security model documents v0.11 cache boundary','v0.11' in security and 'strong' in security.lower() and 'best_effort' in security)
check('README preserves cache/validation guarantees','v0.12.0' in readme and 'cache' in readme.lower() and 'multi-platform' in readme.lower())
check('agent still does not auto-promote','promot' not in runtime.lower() or 'auto-promot' in readme.lower())

failed=[n for n,c in checks if not c]
for n,c in checks: print(('PASS' if c else 'FAIL')+': '+n)
if failed:
    print(f'\n{len(failed)} cache/validation invariant(s) failed',file=sys.stderr)
    sys.exit(1)
print(f'\nAction Cache + Multi-Platform Validation audit passed: {len(checks)} invariants')
